// Package logging configures the process-wide slog logger.
//
// gomplate emits structured logs on stderr. The concrete encoding depends on
// the GOMPLATE_LOG_FORMAT environment variable, falling back to a
// human-friendly console encoding when stderr is a terminal and JSON
// otherwise.
package logging

import (
	"context"
	"fmt"
	"io"
	"log/slog"
	"os"
	"strconv"
	"sync"
	"time"
)

// format names accepted in GOMPLATE_LOG_FORMAT.
const (
	formatJSON    = "json"
	formatLogfmt  = "logfmt"
	formatConsole = "console"
	formatSimple  = "simple"
)

// levelVar lets --verbose raise verbosity after the handler is installed.
var levelVar = new(slog.LevelVar)

func init() {
	levelVar.Set(slog.LevelInfo)
	// Before the command line has been parsed we have no idea which encoding
	// the user wants, and flag-parsing errors must still be reported. Use the
	// bare encoding (no timestamp, no colour) for those.
	slog.SetDefault(slog.New(&textHandler{
		w:         os.Stderr,
		level:     levelVar,
		showLevel: true,
	}))
}

// SetVerbose raises the log level so that Debug records are emitted.
func SetVerbose(v bool) {
	if v {
		levelVar.Set(slog.LevelDebug)
	} else {
		levelVar.Set(slog.LevelInfo)
	}
}

// Init installs the real handler, choosing an encoding based on the
// environment and whether out refers to a terminal.
func Init(out io.Writer, isTerminal bool) {
	opts := &slog.HandlerOptions{Level: levelVar}

	switch os.Getenv("GOMPLATE_LOG_FORMAT") {
	case formatLogfmt:
		slog.SetDefault(slog.New(slog.NewTextHandler(out, opts)))
	case formatConsole:
		slog.SetDefault(slog.New(&textHandler{
			w: out, level: levelVar, showTime: true, showLevel: true, abbrev: true,
			colour: isTerminal,
		}))
	case formatSimple:
		slog.SetDefault(slog.New(&textHandler{w: out, level: levelVar}))
	case formatJSON:
		slog.SetDefault(slog.New(slog.NewJSONHandler(out, opts)))
	default:
		if isTerminal {
			slog.SetDefault(slog.New(&textHandler{
				w: out, level: levelVar, showTime: true, showLevel: true, abbrev: true,
				colour: true,
			}))
		} else {
			slog.SetDefault(slog.New(slog.NewJSONHandler(out, opts)))
		}
	}
}

// IsTerminal reports whether f is attached to a character device.
func IsTerminal(f *os.File) bool {
	if f == nil {
		return false
	}
	st, err := f.Stat()
	if err != nil {
		return false
	}
	return st.Mode()&os.ModeCharDevice != 0
}

const (
	dim   = "\x1b[2m"
	reset = "\x1b[0m"
)

// textHandler renders records as a single line of mostly-unadorned text:
//
//	<time> <level> <message> <key>=<value>...
//
// Any of the time and level columns can be suppressed; the separating spaces
// are kept regardless, which is what produces the double space in front of
// messages in the "simple" encoding.
type textHandler struct {
	mu     sync.Mutex
	w      io.Writer
	level  *slog.LevelVar
	attrs  []slog.Attr
	groups []string

	showTime  bool
	showLevel bool
	abbrev    bool // render levels as three-letter abbreviations
	colour    bool
}

func (h *textHandler) Enabled(_ context.Context, l slog.Level) bool {
	return l >= h.level.Level()
}

func (h *textHandler) WithAttrs(attrs []slog.Attr) slog.Handler {
	if len(attrs) == 0 {
		return h
	}
	c := h.clone()
	c.attrs = append(c.attrs, attrs...)
	return c
}

func (h *textHandler) WithGroup(name string) slog.Handler {
	if name == "" {
		return h
	}
	c := h.clone()
	c.groups = append(c.groups, name)
	return c
}

func (h *textHandler) clone() *textHandler {
	return &textHandler{
		w: h.w, level: h.level,
		attrs:  append([]slog.Attr(nil), h.attrs...),
		groups: append([]string(nil), h.groups...),
		showTime: h.showTime, showLevel: h.showLevel,
		abbrev: h.abbrev, colour: h.colour,
	}
}

func (h *textHandler) Handle(_ context.Context, r slog.Record) error {
	buf := make([]byte, 0, 256)

	if h.showTime && !r.Time.IsZero() {
		buf = h.wrapDim(buf, r.Time.Format("15:04:05"))
	}
	buf = append(buf, ' ')

	if h.showLevel {
		buf = append(buf, h.levelString(r.Level)...)
	}
	buf = append(buf, ' ')

	buf = append(buf, r.Message...)

	for _, a := range h.attrs {
		buf = h.appendAttr(buf, h.groups, a)
	}
	r.Attrs(func(a slog.Attr) bool {
		buf = h.appendAttr(buf, h.groups, a)
		return true
	})
	buf = append(buf, '\n')

	h.mu.Lock()
	defer h.mu.Unlock()
	_, err := h.w.Write(buf)
	return err
}

func (h *textHandler) levelString(l slog.Level) string {
	if !h.abbrev {
		return l.String()
	}
	switch {
	case l < slog.LevelInfo:
		return "DBG"
	case l < slog.LevelWarn:
		return "INF"
	case l < slog.LevelError:
		return "WRN"
	default:
		return "ERR"
	}
}

func (h *textHandler) wrapDim(buf []byte, s string) []byte {
	if h.colour {
		buf = append(buf, dim...)
		buf = append(buf, s...)
		return append(buf, reset...)
	}
	return append(buf, s...)
}

func (h *textHandler) appendAttr(buf []byte, groups []string, a slog.Attr) []byte {
	a.Value = a.Value.Resolve()
	if a.Equal(slog.Attr{}) {
		return buf
	}
	if a.Value.Kind() == slog.KindGroup {
		sub := a.Value.Group()
		if len(sub) == 0 {
			return buf
		}
		g := groups
		if a.Key != "" {
			g = append(append([]string(nil), groups...), a.Key)
		}
		for _, s := range sub {
			buf = h.appendAttr(buf, g, s)
		}
		return buf
	}

	key := a.Key
	for i := len(groups) - 1; i >= 0; i-- {
		key = groups[i] + "." + key
	}

	buf = append(buf, ' ')
	buf = h.wrapDim(buf, key+"=")
	return append(buf, formatValue(a.Value)...)
}

func formatValue(v slog.Value) string {
	switch v.Kind() {
	case slog.KindString:
		return v.String()
	case slog.KindInt64:
		return strconv.FormatInt(v.Int64(), 10)
	case slog.KindUint64:
		return strconv.FormatUint(v.Uint64(), 10)
	case slog.KindFloat64:
		return strconv.FormatFloat(v.Float64(), 'g', -1, 64)
	case slog.KindBool:
		return strconv.FormatBool(v.Bool())
	case slog.KindDuration:
		return v.Duration().String()
	case slog.KindTime:
		return v.Time().Format(time.RFC3339Nano)
	default:
		return fmt.Sprintf("%v", v.Any())
	}
}

