func (s *Set) Add(f *Flag) *Flag {
	if f.DefValue == "" {
		f.DefValue = f.Value.String()
	}
	s.ordered = append(s.ordered, f)
	s.byName[f.Name] = f
	if f.Shorthand != "" {
		s.byShort[f.Shorthand] = f
	}
	return f
}

