type StringSliceValue struct {
	V        *[]string
	TypeName string
	// replaced tracks the first Set so a default can be overwritten rather
	// than appended to.
	replaced bool
}

func (v *StringSliceValue) String() string {
	if len(*v.V) == 0 {
		return ""
	}
	return "[" + strings.Join(*v.V, ",") + "]"
}

func (v *StringSliceValue) Set(s string) error {
	if !v.replaced {
		*v.V = nil
		v.replaced = true
	}
	*v.V = append(*v.V, s)
	return nil
}

func (v *StringSliceValue) Type() string {
	if v.TypeName != "" {
		return v.TypeName
	}
	return "strings"
}

