// Package config models gomplate's configuration: the merged view of the
// config file, environment variables and command-line flags.
package config

import (
	"fmt"
	"net/http"
	"net/url"
	"sort"
	"strings"
	"time"

	"gomplate/internal/yaml"
)

// DataSource is a datasource or template reference: a URL plus any HTTP
// headers to send when reading it.
type DataSource struct {
	URL    *url.URL
	Header http.Header
}

// Plugin is an external command exposed to templates as a function.
type Plugin struct {
	Cmd     string
	Args    []string
	Timeout time.Duration
	Pipe    bool
}

// Config is the complete set of knobs gomplate understands. Field order here
// is also the order used when the configuration is dumped for --verbose.
type Config struct {
	DataSources map[string]DataSource
	Context     map[string]DataSource
	Templates   map[string]DataSource
	Plugins     map[string]Plugin

	In         string
	InputFiles []string
	InputDir   string

	// Excludes holds glob patterns; a leading ! negates the pattern. The
	// --include flag is folded in here as "*" followed by "!<pattern>".
	Excludes          []string
	ExcludeProcessing []string

	OutputMap   string
	OutputFiles []string
	OutputDir   string
	Chmod       string

	LeftDelim  string
	RightDelim string
	MissingKey string

	PluginTimeout time.Duration
	PostExec      []string
	ExecPipe      bool
	Experimental  bool

	// Verbose is not part of the dumped configuration.
	Verbose bool
}

// missingKeyValues enumerates the accepted --missing-key settings. The empty
// string is allowed and means "unset".
var missingKeyValues = []string{"", "error", "zero", "default", "invalid"}

// String renders the configuration the way --verbose reports it: a YAML
// document containing only the fields that carry information.
func (c *Config) String() string {
	var b strings.Builder
	b.WriteString("---\n")

	writeSources(&b, "datasources", c.DataSources)
	writeSources(&b, "context", c.Context)
	writeSources(&b, "templates", c.Templates)
	writePlugins(&b, c.Plugins)

	writeScalar(&b, "in", c.In)
	writeFlowList(&b, "inputFiles", c.InputFiles)
	writeScalar(&b, "inputDir", c.InputDir)
	writeBlockList(&b, "excludes", c.Excludes)
	writeBlockList(&b, "excludeProcessing", c.ExcludeProcessing)
	writeScalar(&b, "outputMap", c.OutputMap)
	writeFlowList(&b, "outputFiles", c.OutputFiles)
	writeScalar(&b, "outputDir", c.OutputDir)
	writeScalar(&b, "chmod", c.Chmod)

	writeScalar(&b, "leftDelim", c.LeftDelim)
	writeScalar(&b, "rightDelim", c.RightDelim)
	writeScalar(&b, "missingKey", c.MissingKey)

	if c.PluginTimeout != 0 {
		fmt.Fprintf(&b, "pluginTimeout: %s\n", c.PluginTimeout)
	}
	writeFlowList(&b, "postExec", c.PostExec)
	if c.ExecPipe {
		b.WriteString("execPipe: true\n")
	}
	if c.Experimental {
		b.WriteString("experimental: true\n")
	}

	return b.String()
}

func writeScalar(b *strings.Builder, key, val string) {
	if val == "" {
		return
	}
	fmt.Fprintf(b, "%s: %s\n", key, yaml.FormatScalar(val))
}

func writeFlowList(b *strings.Builder, key string, vals []string) {
	if len(vals) == 0 {
		return
	}
	parts := make([]string, len(vals))
	for i, v := range vals {
		parts[i] = yaml.FormatFlowScalar(v)
	}
	fmt.Fprintf(b, "%s: [%s]\n", key, strings.Join(parts, ", "))
}

func writeBlockList(b *strings.Builder, key string, vals []string) {
	if len(vals) == 0 {
		return
	}
	fmt.Fprintf(b, "%s:\n", key)
	for _, v := range vals {
		fmt.Fprintf(b, "  - %s\n", yaml.FormatScalar(v))
	}
}

func writeSources(b *strings.Builder, key string, srcs map[string]DataSource) {
	if len(srcs) == 0 {
		return
	}
	fmt.Fprintf(b, "%s:\n", key)
	for _, alias := range sortedKeys(srcs) {
		src := srcs[alias]
		fmt.Fprintf(b, "  %s:\n", yaml.FormatScalar(alias))
		if len(src.Header) == 0 {
			b.WriteString("    header: {}\n")
		} else {
			b.WriteString("    header:\n")
			names := make([]string, 0, len(src.Header))
			for n := range src.Header {
				names = append(names, n)
			}
			sort.Strings(names)
			for _, n := range names {
				fmt.Fprintf(b, "      %s:\n", yaml.FormatScalar(n))
				for _, v := range src.Header[n] {
					fmt.Fprintf(b, "        - %s\n", yaml.FormatScalar(v))
				}
			}
		}
		url := ""
		if src.URL != nil {
			url = src.URL.String()
		}
		fmt.Fprintf(b, "    url: %s\n", yaml.FormatScalar(url))
	}
}

func writePlugins(b *strings.Builder, plugins map[string]Plugin) {
	if len(plugins) == 0 {
		return
	}
	b.WriteString("plugins:\n")
	for _, name := range sortedKeys(plugins) {
		p := plugins[name]
		fmt.Fprintf(b, "  %s:\n", yaml.FormatScalar(name))
		fmt.Fprintf(b, "    cmd: %s\n", yaml.FormatScalar(p.Cmd))
		if len(p.Args) > 0 {
			fmt.Fprintf(b, "    args: [%s]\n", strings.Join(mapf(p.Args, yaml.FormatFlowScalar), ", "))
		}
		if p.Timeout != 0 {
			fmt.Fprintf(b, "    timeout: %s\n", p.Timeout)
		}
		if p.Pipe {
			b.WriteString("    pipe: true\n")
		}
	}
}

func mapf(in []string, f func(string) string) []string {
	out := make([]string, len(in))
	for i, s := range in {
		out[i] = f(s)
	}
	return out
}

func sortedKeys[V any](m map[string]V) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

// ApplyDefaults fills in the values gomplate assumes when nothing else says
// otherwise. It is called after the config file and flags have been merged.
func (c *Config) ApplyDefaults() {
	if c.InputDir != "" && c.OutputDir == "" && c.OutputMap == "" {
		c.OutputDir = "."
	}
	if c.InputDir == "" && len(c.InputFiles) == 0 && c.In == "" {
		c.InputFiles = []string{"-"}
	}
