// something derived from VCS metadata so that builds are reproducible.
const version = "0.0.0"

// build accompanies version in verbose logging.
const build = "HEAD"

// options is the raw, pre-merge view of the command line. Everything is
// captured as strings here; interpretation happens in toConfig.
type options struct {
	datasources       []string
	datasourceHeaders []string
	contexts          []string
	plugins           []string

	inputFiles []string
	in         string
	inputDir   string

	excludes          []string
	excludeProcessing []string
	includes          []string

	outputFiles []string
	templates   []string
	outputDir   string
	outputMap   string
	chmod       string

	execPipe   bool
	leftDelim  string
	rightDelim string
	missingKey string

	experimental bool
	verbose      bool
	configFile   string

	help        bool
	showVersion bool
}

// newFlagSet declares every flag in the order they appear in the usage output.
func newFlagSet(o *options) *flags.Set {
	fs := flags.New("gomplate")

