			DefValue: def,
		})
	}
	str := func(name, short, typeName, usage string, dst *string, def string) {
		f := fs.Add(&flags.Flag{
			Name: name, Shorthand: short, Usage: usage,
			Value:    stringValue{dst, typeName},
			DefValue: def,
		})
		_ = f
	}
	boolean := func(name, short, usage string, dst *bool) {
		fs.Add(&flags.Flag{
			Name: name, Shorthand: short, Usage: usage,
			Value:       flags.BoolValue{V: dst},
			NoOptDefVal: "true",
			DefValue:    "",
		})
	}

	slice("datasource", "d", "datasource",
		"datasource in alias=URL form. Specify multiple times to add multiple sources.",
		&o.datasources, "")
	slice("datasource-header", "H", "header",
		"HTTP header field in 'alias=Name: value' form to be provided on HTTP-based data sources. Multiples can be set.",
		&o.datasourceHeaders, "")
