	boolean("help", "h", "help for gomplate", &o.help)
	boolean("version", "v", "version for gomplate", &o.showVersion)

	return fs
}

// stringValue is a flags.Value whose Type() names a custom placeholder.
type stringValue struct {
	v        *string
	typeName string
}

func (s stringValue) String() string { return *s.v }
func (s stringValue) Set(v string) error {
	*s.v = v
	return nil
}
func (s stringValue) Type() string { return s.typeName }

// UsageBody renders the "Usage:" section, exactly as shown after an error.
func UsageBody(fs *flags.Set) string {
	var b strings.Builder
	b.WriteString("Usage:\n  gomplate [flags]\n\nFlags:\n")
	b.WriteString(fs.Usages())
	return b.String()
}

// Help renders the --help output.
func Help(fs *flags.Set) string {
	return Description + "\n\n" + UsageBody(fs)
}

// printUsage writes the usage block plus a trailing blank line, which is what
// gomplate emits on stdout when the command line is rejected.
func printUsage(w io.Writer, fs *flags.Set) {
	fmt.Fprint(w, UsageBody(fs)+"\n")
}

// dumpConfig logs the merged configuration the way --verbose reports it.
func dumpConfig(cfg *config.Config) {
	slog.Debug("config is:\n"+cfg.String(), "version", version, "build", build)
}

