// plain scalar; fall back to single quotes when plain style would be
// misparsed; use double quotes when the text would otherwise resolve to a
// non-string type or contains characters that cannot appear literally.
package yamlfmt

import (
	"fmt"
	"strings"
	"unicode"
	"unicode/utf8"
)

// Scalar renders s as a YAML scalar suitable for use as a value in block
// context. Strings containing newlines are not handled here; callers that can
// receive them should use a full emitter.
func Scalar(s string) string {
	switch {
	case ResolvesToNonString(s), !printable(s):
		return DoubleQuote(s)
	case plainAllowed(s, false):
		return s
	default:
		return SingleQuote(s)
	}
}

// FlowScalar renders s for use inside flow context ([...] or {...}), where a
// few extra characters terminate a plain scalar.
func FlowScalar(s string) string {
	switch {
	case ResolvesToNonString(s), !printable(s):
		return DoubleQuote(s)
	case plainAllowed(s, true):
		return s
	default:
		return SingleQuote(s)
	}
}

// SingleQuote renders s in single-quoted style, doubling any apostrophes.
func SingleQuote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", "''") + "'"
}

// DoubleQuote renders s in double-quoted style with YAML escapes.
func DoubleQuote(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, r := range s {
		switch r {
		case '"':
			b.WriteString(`\"`)
		case '\\':
			b.WriteString(`\\`)
		case '\n':
			b.WriteString(`\n`)
		case '\r':
			b.WriteString(`\r`)
		case '\t':
			b.WriteString(`\t`)
		case 0:
			b.WriteString(`\0`)
		case 0x07:
			b.WriteString(`\a`)
		case 0x08:
			b.WriteString(`\b`)
		case 0x0b:
			b.WriteString(`\v`)
		case 0x0c:
			b.WriteString(`\f`)
		case 0x1b:
			b.WriteString(`\e`)
		case 0x85:
			b.WriteString(`\N`)
		case 0xa0:
			b.WriteString(`\_`)
		case 0x2028:
			b.WriteString(`\L`)
		case 0x2029:
			b.WriteString(`\P`)
		default:
			switch {
			case r == utf8.RuneError:
				b.WriteString(`�`)
			case r < 0x20:
				fmt.Fprintf(&b, `\x%02x`, r)
			case r > 0x7e && !unicode.IsPrint(r):
				if r > 0xffff {
					fmt.Fprintf(&b, `\U%08x`, r)
				} else {
					fmt.Fprintf(&b, `\u%04x`, r)
				}
			default:
				b.WriteRune(r)
			}
		}
	}
	b.WriteByte('"')
	return b.String()
}

// printable reports whether every rune in s may appear literally in a plain or
// single-quoted scalar. Tabs are excluded because an emitter cannot reproduce
// their column semantics reliably.
func printable(s string) bool {
	if !utf8.ValidString(s) {
		return false
	}
	for _, r := range s {
		switch r {
		case '\n', '\t', '\r':
			return false
		}
		if r < 0x20 || (r >= 0x7f && r <= 0x9f) {
			return false
		}
	}
	return true
}

// indicators may not begin a plain scalar under any circumstances.
const indicators = ",[]{}#&*!|>'\"%@`"

// plainAllowed reports whether s can be written without quotes. The flow
// parameter widens the set of forbidden characters to those that terminate a
// scalar inside [] or {}.
func plainAllowed(s string, flow bool) bool {
	if s == "" {
		return false
	}
	// Leading or trailing whitespace would be stripped by the parser.
	if strings.HasPrefix(s, " ") || strings.HasSuffix(s, " ") {
		return false
	}
	if strings.Contains(s, indicators[:1]) && flow {
		return false
	}

	first, _ := utf8.DecodeRuneInString(s)
	if strings.ContainsRune(indicators, first) {
		return false
	}
	// "-", "?" and ":" are only indicators when they stand alone or are
	// followed by a space, so "-x" and "?x" are fine but "- x" is not.
	if first == '-' || first == '?' || first == ':' {
		if len(s) == 1 || s[1] == ' ' {
			return false
		}
	}
	// A colon followed by a space, or a hash preceded by a space, ends the
	// scalar wherever it occurs.
	if strings.Contains(s, ": ") || strings.HasSuffix(s, ":") {
		return false
	}
	if strings.Contains(s, " #") {
		return false
	}
	if flow {
		if strings.ContainsAny(s, ",[]{}") {
			return false
		}
	}
	return true
}

