package yamlfmt

import (
	"encoding/json"
	"os"
	"testing"
)

// TestScalarAgainstFixture checks the quoting rules against a table of
// observed renderings recorded in testdata/scalars.json.
func TestScalarAgainstFixture(t *testing.T) {
	data, err := os.ReadFile("testdata/scalars.json")
	if err != nil {
		t.Fatalf("reading fixture: %v", err)
	}
	var rows []struct {
		In    string `json:"in"`
		Block string `json:"block"`
	}
	if err := json.Unmarshal(data, &rows); err != nil {
		t.Fatalf("decoding fixture: %v", err)
	}
	if len(rows) == 0 {
		t.Fatal("fixture is empty")
	}

	for _, row := range rows {
		if got := Scalar(row.In); got != row.Block {
			t.Errorf("Scalar(%q) = %s, want %s", row.In, got, row.Block)
		}
	}
}

func TestFlowScalar(t *testing.T) {
	cases := map[string]string{
		"x":    "x",
		"-":    "'-'",
		"a,b":  "'a,b'",
		"a[b":  "'a[b'",
		"a}b":  "'a}b'",
		"true": `"true"`,
		"a b":  "a b",
	}
	for in, want := range cases {
		if got := FlowScalar(in); got != want {
			t.Errorf("FlowScalar(%q) = %s, want %s", in, got, want)
		}
	}
}

func TestResolvesToNonString(t *testing.T) {
	nonStrings := []string{"", "~", "null", "true", "off", "N", "1", "-0", "0644", "0x1F",
		"0b101", "0o17", "1_000", "1.5", ".inf", ".NaN", "12:30", "1:2:3", "2020-1-2",
		"2020-01-02T03:04:05Z", "2020-01-02 03:04:05", "1e3"}
	for _, s := range nonStrings {
		if !ResolvesToNonString(s) {
			t.Errorf("ResolvesToNonString(%q) = false, want true", s)
		}
	}

	strs := []string{"x", "inf", "nan", "Inf", "e", "E", "null_", "_x", "o17", "0x", "0b",
		"0o", "1e", "--1", "..", "2020-01-02t03:04:05z", "z", "tRue", "nULL", "1__"}
	for _, s := range strs {
		if ResolvesToNonString(s) {
			t.Errorf("ResolvesToNonString(%q) = true, want false", s)
		}
	}
}

