package yamlfmt

import (
	"strconv"
	"strings"
	"time"
)

// timestampLayouts are the shapes a plain scalar may take to be read back as a
// timestamp rather than a string. Note that the zone designator must be an
// upper-case Z, so "…t03:04:05z" is *not* a timestamp.
var timestampLayouts = []string{
	"2006-1-2T15:4:5.999999999Z07:00",
	"2006-1-2t15:4:5.999999999Z07:00",
	"2006-1-2 15:4:5.999999999",
	"2006-1-2",
}

// nullValues, boolValues use YAML 1.1 spellings, which is what emitters must
// assume in order to stay compatible with older parsers.
var nullValues = map[string]bool{
	"": true, "~": true, "null": true, "Null": true, "NULL": true,
}

var boolValues = map[string]bool{
	"y": true, "Y": true, "yes": true, "Yes": true, "YES": true,
	"n": true, "N": true, "no": true, "No": true, "NO": true,
	"true": true, "True": true, "TRUE": true,
	"false": true, "False": true, "FALSE": true,
	"on": true, "On": true, "ON": true,
	"off": true, "Off": true, "OFF": true,
}

// ResolvesToNonString reports whether a plain scalar spelled s would be read
// back as something other than a string — a null, bool, number or timestamp.
// Such strings must be quoted on output.
func ResolvesToNonString(s string) bool {
	if nullValues[s] || boolValues[s] {
		return true
	}
	// Numbers and timestamps always begin with a digit or a sign/dot.
	if s == "" {
		return true
	}
	switch c := s[0]; {
	case c >= '0' && c <= '9', c == '-', c == '+', c == '.':
	default:
		return false
	}
	return isYAMLInt(s) || isYAMLFloat(s) || isTimestamp(s)
}

func isTimestamp(s string) bool {
	for _, layout := range timestampLayouts {
		if _, err := time.Parse(layout, s); err == nil {
			return true
		}
	}
	return false
}

// isYAMLInt covers decimal, hex, octal (both 0o and the legacy leading zero),
// binary and sexagesimal integers, all of which may contain underscores.
func isYAMLInt(s string) bool {
	body, ok := splitSign(s)
	if !ok {
		return false
	}
	switch {
	case strings.HasPrefix(body, "0x"), strings.HasPrefix(body, "0X"):
		return allDigits(strip(body[2:]), 16)
	case strings.HasPrefix(body, "0o"), strings.HasPrefix(body, "0O"):
		return allDigits(strip(body[2:]), 8)
	case strings.HasPrefix(body, "0b"), strings.HasPrefix(body, "0B"):
		return allDigits(strip(body[2:]), 2)
	case strings.Contains(body, ":"):
		return isSexagesimal(body, false)
	case len(body) > 1 && body[0] == '0':
		return allDigits(strip(body[1:]), 8)
	default:
		return allDigits(strip(body), 10)
	}
}

// isYAMLFloat covers ordinary decimal floats, exponents, the .inf/.nan
// spellings and sexagesimal floats.
func isYAMLFloat(s string) bool {
	body, ok := splitSign(s)
	if !ok {
		return false
	}
	switch body {
	case ".inf", ".Inf", ".INF", ".nan", ".NaN", ".NAN":
		return true
	}
	if strings.Contains(body, ":") {
		return isSexagesimal(body, true)
	}
	body = strip(body)
	if body == "" || body == "." {
		return false
	}
	// Reject forms strconv accepts but YAML does not, such as hex floats and
	// the words "inf"/"nan".
	if strings.ContainsAny(body, "xXpPnNiI") {
		return false
	}
	_, err := strconv.ParseFloat(body, 64)
	return err == nil
}

// isSexagesimal validates base-60 notation such as 12:30 or 1:2:3.5.
func isSexagesimal(s string, allowFraction bool) bool {
	parts := strings.Split(s, ":")
	if len(parts) < 2 {
		return false
	}
	for i, p := range parts {
		p = strip(p)
		if p == "" {
			return false
		}
		last := i == len(parts)-1
		if allowFraction && last {
			if _, err := strconv.ParseFloat(p, 64); err != nil {
				return false
			}
			continue
		}
		if !allDigits(p, 10) {
			return false
		}
	}
	return true
}

// splitSign removes a leading + or - and rejects a sign on its own.
func splitSign(s string) (string, bool) {
	if s == "" {
		return "", false
	}
	if s[0] == '+' || s[0] == '-' {
		s = s[1:]
	}
	return s, s != ""
}

// strip removes the digit separators YAML 1.1 permits.
func strip(s string) string { return strings.ReplaceAll(s, "_", "") }

func allDigits(s string, base int) bool {
	if s == "" {
		return false
	}
	for _, r := range s {
		var v int
		switch {
		case r >= '0' && r <= '9':
			v = int(r - '0')
		case r >= 'a' && r <= 'f':
			v = int(r-'a') + 10
		case r >= 'A' && r <= 'F':
			v = int(r-'A') + 10
		default:
			return false
		}
		if v >= base {
			return false
		}
	}
	return true
}

